changeSet.sql:
DELETE FROM jhi_user_authority ua
WHERE ua.authority_name NOT IN ('ROLE_USER','ROLE_COMMUNITY_MANAGER','ROLE_EVENT_MANAGER','ROLE_MODERATOR','ROLE_ADMIN','ROLE_SUPER_ADMIN');
INSERT INTO jhi_user_authority(user_id,authority_name)
  SELECT u.id,'ROLE_USER' FROM jhi_user u
  WHERE NOT EXISTS (SELECT 1 FROM jhi_user_authority ua WHERE ua.user_id=u.id);
DELETE FROM jhi_user_authority ua
WHERE ua.user_id IN (SELECT id FROM jhi_user WHERE login='ademdemirdev') AND ua.authority_name <> 'ROLE_SUPER_ADMIN';
INSERT INTO jhi_user_authority(user_id,authority_name)
  SELECT id,'ROLE_SUPER_ADMIN' FROM jhi_user u WHERE u.login='ademdemirdev'
  AND NOT EXISTS (SELECT 1 FROM jhi_user_authority ua WHERE ua.user_id=u.id);
